            let hi = lower_hex_val(group[gi])?;
            let lo = lower_hex_val(group[gi + 1])?;
            out[out_pos] = (hi << 4) | lo;
            out_pos += 1;
            gi += 2;
        }
    }
    Some((prefix, out))
}

fn lower_hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        _ => None,
