        pos += 1;
        let frac_start = pos;
        while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
            pos += 1;
        }
        if pos == frac_start {
            return None;
        }
        let frac = &s[frac_start..pos];
        let mut ms_digits = [b'0'; 3];
        for (i, slot) in ms_digits.iter_mut().enumerate() {
            if let Some(&b) = frac.as_bytes().get(i) {
