        Some(b'Z') | Some(b'z') => {
            pos += 1;
            0i64
        }
        Some(b'+') | Some(b'-') => {
            let sign = if bytes[pos] == b'+' { 1 } else { -1 };
            pos += 1;
            let oh = two(pos)?;
            pos += 2;
            if bytes.get(pos) != Some(&b':') {
                return None;
            }
            pos += 1;
            let om = two(pos)?;
            pos += 2;
            sign * (oh * 60 + om)
