async fn write_frame_retained<S: PackSink>(sink: &mut S, kind: u8, flags: u8, raw_len: Option<u64>, stored_payload: &[u8]) -> Result<(u64, [u8; 32]), ProtocolError> where ProtocolError: From<S::Error> {
    let mut raw_len_bytes = [0u8; 10];
    let raw_len_count = match raw_len {
        Some(value) => fixed_varint(value, &mut raw_len_bytes).len(),
        None => 0,
    };
    let raw_len_bytes = &raw_len_bytes[..raw_len_count];
    let body_len = 2u64.checked_add(raw_len_bytes.len() as u64).and_then(|len| len.checked_add(stored_payload.len() as u64)).ok_or(ProtocolError::LimitExceeded("frame body length overflow"))?;
    let mut body_len_bytes = [0u8; 10];
    let body_len_bytes = fixed_varint(body_len, &mut body_len_bytes);
    let frame_len = body_len_bytes.len().checked_add(body_len as usize).and_then(|len| len.checked_add(8)).ok_or(ProtocolError::LimitExceeded("frame length overflow"))?;
    let back_len = u32::try_from(frame_len).map_err(|_| ProtocolError::LimitExceeded("frame exceeds u32 back_len (4 GiB cap)"))?;
    let fixed = [kind, flags];
    let mut crc = crate::codec::Crc32cCursor::new();
    crc.update_page(&fixed);
    crc.update_page(raw_len_bytes);
    crc.update_page(stored_payload);
    let crc = crc.finish().to_le_bytes();
    let back_len = back_len.to_le_bytes();
    let mut digest = semio_framework_hash::Hasher::new();
    for fragment in [body_len_bytes, fixed.as_slice(), raw_len_bytes, stored_payload, crc.as_slice(), back_len.as_slice()] {
        digest.update(fragment);
        sink.write_all(fragment).await?;
    }
    Ok((frame_len as u64, *digest.finalize().as_bytes()))
}

/// 🚨️ Builds a `crate::ProtocolError::Malformed` for this crate's own structural
/// checks (distinct from `crate::codec::PackError`-wrapped errors, which cover pack-primitive-level
/// failures like truncation/varint overflow).
async fn malformed(what: &'static str, offset: u64, detail: impl Into<String>) -> ProtocolError {
    ProtocolError::Malformed { what, offset, detail: detail.into() }
}

/// 📦️ One parsed, CRC-verified record frame borrowed zero-copy from the buffer it was read
/// from. `stored` is exactly the on-disk payload bytes — compressed iff `flags & FRAME_FLAG_COMPRESSED`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RecordFrame<'a> {
    pub kind: u8,
    pub flags: u8,
    pub offset: u64,
    pub stored: &'a [u8],
    pub raw_len: Option<u64>,
}

impl<'a> RecordFrame<'a> {
    /// 📤️ The on-disk payload bytes: identical to the caller's original data iff
    /// `!compressed`; otherwise the caller must decompress via a `crate::codec::CompressionCodec`
    /// keyed by `crate::frame_codec_id(self.flags).await`, targeting `self.raw_len` bytes.
    pub async fn payload(&self) -> &'a [u8] {
        self.stored
    }

    /// 📏️ Total on-disk bytes this frame occupies (the value its trailing `back_len` field
    /// carries), recomputed from the visible fields rather than cached — every input to the
    /// computation is already public state, so there is nothing to desync.
    pub async fn frame_len(&self) -> u64 {
        let raw_len_width = match self.raw_len {
            Some(v) => varint_width(v).await,
            None => 0,
        };
        let body_len = 2 + raw_len_width + self.stored.len() as u64;
        varint_width(body_len).await + body_len + 8
    }
}

/// 👓️ Zero-copy forward parse of one frame starting at `bytes[pos..]`. Validates `body_len`
/// bounds, `crc32c` (over `kind..payload`), and the `back_len` self-echo before returning. Returns
/// `(frame, next_pos)` so callers (both cursors below) can advance without recomputing `frame_len`.
async fn decode_frame_in_slice(bytes: &[u8], pos: usize) -> Result<(RecordFrame<'_>, usize), ProtocolError> {
    let mut cursor = pos;
    let body_len = crate::codec::read_varint_u64(bytes, &mut cursor)?;
    if body_len < 2 {
        return Err(malformed("frame body_len", pos as u64, "body_len smaller than kind+flags (2 bytes)").await);
    }
    let body_start = cursor;
    let body_end = body_start.checked_add(body_len as usize).ok_or(ProtocolError::LimitExceeded("frame body_len overflows usize"))?;
    let trailer_end = body_end.checked_add(8).ok_or(ProtocolError::LimitExceeded("frame trailer offset overflows usize"))?;
    if trailer_end > bytes.len() {
        return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::Truncated(body_start as u64))));
    }
    let body = &bytes[body_start..body_end];
    let kind = body[0];
    let flags = body[1];
    let compressed = flags & FRAME_FLAG_COMPRESSED != 0;
    let mut payload_start = 2usize;
    let raw_len = if compressed {
        let mut p = payload_start;
        let v = crate::codec::read_varint_u64(body, &mut p)?;
        payload_start = p;
        Some(v)
    } else {
        None
    };
    let stored = &body[payload_start..];
    let stored_crc = u32::from_le_bytes(bytes[body_end..body_end + 4].try_into().unwrap());
    let computed_crc = crate::codec::crc32c(body);
    if stored_crc != computed_crc {
        return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::ChecksumMismatch { segment: "frame", offset: body_end as u64 })));
    }
    let back_len = u32::from_le_bytes(bytes[body_end + 4..trailer_end].try_into().unwrap()) as usize;
    let frame_len = trailer_end - pos;
    if back_len != frame_len {
        return Err(ProtocolError::FrameFraming(pos as u64));
    }
    Ok((RecordFrame { kind, flags, offset: pos as u64, stored, raw_len }, trailer_end))
}

/// ➡️ Forward, zero-copy iteration over a contiguous record stream (a whole `.spr` buffer,
/// or any already-decompressed span of ordinary frames — e.g. an inflated `REC_SEALED` batch).
pub struct FrameCursor<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> FrameCursor<'a> {
    /// 🚀️ Positions a cursor over `bytes`, ready to read the frame starting at `start_offset`
    /// (typically `HEADER_SIZE` for a whole file).
    pub async fn new(bytes: &'a [u8], start_offset: u64) -> Self {
        Self { bytes, pos: start_offset as usize }
    }

    /// ⏭️ Parses and returns the next frame, or `None` at exact end-of-buffer. A short
    /// leftover (fewer bytes than a minimal frame needs) is a real parse error, not `None` — only
    /// `recover`'s forward scan is expected to encounter a torn tail and must stop before it.
    pub async fn next_frame(&mut self) -> Result<Option<RecordFrame<'a>>, ProtocolError> {
        if self.pos >= self.bytes.len() {
            return Ok(None);
        }
        let (frame, next_pos) = decode_frame_in_slice(self.bytes, self.pos).await?;
        self.pos = next_pos;
        Ok(Some(frame))
    }
}

/// ⬅️ Backward, zero-copy, O(1)-per-step iteration over a contiguous record stream, walking
/// via each frame's trailing `back_len` rather than re-scanning from the start.
///
/// Unlike `FrameCursor::new`, `at_end` takes no `start_offset` — it has no way to know where a
/// leading file header ends, so `bytes` must be a pure record-stream span (e.g. `&file[HEADER_SIZE..]`,
/// or an inflated `REC_SEALED` batch) with nothing but ordinary frames in it; `prev_frame` returns
/// `None` exactly at `pos == 0`. A caller walking the whole file backward slices the header off
/// first (or stops once a frame's `offset` reaches `HEADER_SIZE`, since it always knows that bound).
pub struct ReverseFrameCursor<'a> {
    bytes: &'a [u8],
    pos: usize,
}

/// 📏️ The smallest possible on-disk frame: a 1-byte `body_len` varint (value 2, the minimum
/// legal body_len), 1 kind byte, 1 flags byte, 4 crc32c bytes, 4 back_len bytes.
const MIN_FRAME_LEN: usize = 11;

impl<'a> ReverseFrameCursor<'a> {
    /// 🏁️ Positions a cursor just past the last byte of `bytes`, ready to read the final frame.
    pub async fn at_end(bytes: &'a [u8]) -> Self {
        Self { bytes, pos: bytes.len() }
    }

    /// ⏮️ Reads the trailing `back_len`, jumps back that many bytes, forward-parses from
    /// there, and requires the reproduced end offset to equal the cursor's current position —
    /// exactly the contract's reverse-scan algorithm. `None` at exact start-of-stream.
    pub async fn prev_frame(&mut self) -> Result<Option<RecordFrame<'a>>, ProtocolError> {
        if self.pos == 0 {
            return Ok(None);
        }
        if self.pos < MIN_FRAME_LEN {
            return Err(ProtocolError::FrameFraming(self.pos as u64));
        }
        let back_len = u32::from_le_bytes(self.bytes[self.pos - 4..self.pos].try_into().unwrap()) as usize;
        if back_len < MIN_FRAME_LEN || back_len > self.pos {
            return Err(ProtocolError::FrameFraming(self.pos as u64));
        }
        let frame_start = self.pos - back_len;
        let (frame, next_pos) = decode_frame_in_slice(self.bytes, frame_start).await?;
        if next_pos != self.pos {
            return Err(ProtocolError::FrameFraming(self.pos as u64));
        }
        self.pos = frame_start;
        Ok(Some(frame))
    }
}
//#endregion 🔖️Frame

//#region 🔖️Commit
/// 📏️ Every commit frame's fixed total on-disk size: `1(body_len, single byte since 65 <
/// 128) + 1(kind) + 1(flags) + 64(payload) + 4(crc32c) + 4(back_len)`.
pub const COMMIT_FRAME_LEN: u64 = 75;
/// 📏️ Fixed size of a `REC_COMMIT` frame's payload, in bytes.
pub const COMMIT_PAYLOAD_LEN: usize = 64;

/// ⛓️ The decoded fields of a `REC_COMMIT` frame's fixed 64-byte payload. Public — this is
/// the only way for a downstream crate (`protocol_history`'s `FrontierSummary.last_commit_seq`/
/// `.chain_hash`, `protocol_materialize`, `protocol_cli`'s `hash`/`inspect` subcommands) to read a
/// commit's chain state without re-deriving this crate's private byte offsets.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CommitPayload {
    pub commit_seq: u64,
    pub prev_commit_offset: u64,
    pub records_len: u64,
    pub record_count: u32,
    pub chain_hash: [u8; 32],
}

/// ✍️ Serializes a commit's fixed 64-byte payload per the contract's exact field offsets.
async fn write_commit_payload(commit_seq: u64, prev_commit_offset: u64, records_len: u64, record_count: u32, chain_hash: &[u8; 32]) -> [u8; COMMIT_PAYLOAD_LEN] {
    let mut buf = [0u8; COMMIT_PAYLOAD_LEN];
    buf[0..8].copy_from_slice(&commit_seq.to_le_bytes());
    buf[8..16].copy_from_slice(&prev_commit_offset.to_le_bytes());
    buf[16..24].copy_from_slice(&records_len.to_le_bytes());
    buf[24..28].copy_from_slice(&record_count.to_le_bytes());
    buf[32..64].copy_from_slice(chain_hash);
    buf
}

/// 📖️ Parses a commit frame's payload; the only structural requirement is the exact 64-byte
/// length (already implied by `COMMIT_FRAME_LEN`, but checked directly since callers may hand this
/// any `stored` slice, e.g. during `recover`'s source-backed reads). Public per the `CommitPayload`
/// doc comment above — the sole intended entry point for decoding a `RecordFrame`'s `stored` bytes
/// once a caller has confirmed `kind == crate::REC_COMMIT` via `FrameCursor`/`ReverseFrameCursor`.
pub fn parse_commit_payload(payload: &[u8]) -> Result<CommitPayload, ProtocolError> {
    if payload.len() != COMMIT_PAYLOAD_LEN {
        return Err(ProtocolError::Malformed { what: "commit payload", offset: 0, detail: format!("expected {COMMIT_PAYLOAD_LEN} bytes, got {}", payload.len()) });
    }
    let commit_seq = u64::from_le_bytes(payload[0..8].try_into().unwrap());
    let prev_commit_offset = u64::from_le_bytes(payload[8..16].try_into().unwrap());
    let records_len = u64::from_le_bytes(payload[16..24].try_into().unwrap());
    let record_count = u32::from_le_bytes(payload[24..28].try_into().unwrap());
    let mut chain_hash = [0u8; 32];
    chain_hash.copy_from_slice(&payload[32..64]);
    Ok(CommitPayload { commit_seq, prev_commit_offset, records_len, record_count, chain_hash })
}
//#endregion 🔖️Commit

//#region 🔖️Writer
/// ⚙️ Header flags to open a `.spr` file with.
#[derive(Clone, Copy, Debug, Default)]
pub struct WriteOptions {
    pub required_flags: u32,
    pub optional_flags: u32,
}

/// 🗜️ `(compressed, raw_len, stored_bytes)` — `Cow::Borrowed` for the identity codec avoids
/// copying an already caller-owned payload slice.
type PreparedPayload<'a> = (bool, Option<u64>, std::borrow::Cow<'a, [u8]>);

/// 🗜️ Resolves `codec` for one `write_record` call.
async fn prepare_payload(codec: crate::codec::ids::CodecId, payload: &[u8]) -> Result<PreparedPayload<'_>, ProtocolError> {
    match codec.0 {
        0 => Ok((false, None, std::borrow::Cow::Borrowed(payload))),
        1 => {
            #[cfg(feature = "deflate")]
            {
                let compressed = crate::codec::DeflateCodec.compress(payload)?;
                Ok((true, Some(payload.len() as u64), std::borrow::Cow::Owned(compressed)))
            }
            #[cfg(not(feature = "deflate"))]
            {
                let _ = payload;
                Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::UnsupportedCodec(1))))
            }
        }
        other => Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::UnsupportedCodec(other)))),
    }
}

/// ✒️ Streaming `.spr` builder: writes the header, then any number of records via
/// `write_record`, periodically closed off with `commit` — which hash-chains everything written
/// since the previous commit (or the header, for the first).await. The hot path (`write_record`) is
/// allocation-light: identity payloads and frame metadata stream directly into the retained sink.
pub struct SprWriter<S: PackSink> {
    sink: S,
    running_chain_hash: [u8; 32],
    pending_chain_hasher: semio_framework_hash::Hasher,
    pending_records_len: u64,
    pending_record_count: u32,
    next_commit_seq: u64,
    last_commit_offset: Option<u64>,
}

pub struct SprIdentityRecord<'a, S: PackSink> {
    owner: &'a mut SprWriter<S>,
    start_offset: u64,
    payload_len: usize,
    written: usize,
    frame_len: u64,
    crc: crate::codec::Crc32cCursor,
    digest: semio_framework_hash::Hasher,
}

impl<'a, S: PackSink> SprIdentityRecord<'a, S> where ProtocolError: From<S::Error> {
    pub async fn write_fragment(&mut self, fragment: &[u8]) -> Result<(), ProtocolError> {
        self.written = self.written.checked_add(fragment.len()).ok_or(ProtocolError::LimitExceeded("record payload length overflow"))?;
        if self.written > self.payload_len {
            return Err(ProtocolError::LimitExceeded("record payload exceeded retained frame reservation"));
        }
        self.crc.update_page(fragment);
        self.digest.update(fragment);
        self.owner.sink.write_all(fragment).await?;
        Ok(())
    }

    pub async fn finish(mut self) -> Result<u64, ProtocolError> {
        if self.written != self.payload_len {
            return Err(ProtocolError::LimitExceeded("record payload ended before retained frame reservation"));
        }
        let crc = self.crc.finish().to_le_bytes();
        let back_len = u32::try_from(self.frame_len).map_err(|_| ProtocolError::LimitExceeded("frame exceeds u32 back_len (4 GiB cap)"))?.to_le_bytes();
        for fragment in [crc.as_slice(), back_len.as_slice()] {
            self.digest.update(fragment);
            self.owner.sink.write_all(fragment).await?;
        }
        self.owner.pending_chain_hasher.update(self.digest.finalize().as_bytes());
        self.owner.pending_records_len = self.owner.pending_records_len.checked_add(self.frame_len).ok_or(ProtocolError::LimitExceeded("records length overflow"))?;
        self.owner.pending_record_count = self.owner.pending_record_count.checked_add(1).ok_or(ProtocolError::LimitExceeded("record_count exceeds u32 per commit generation"))?;
        Ok(self.start_offset)
    }
}

impl<S: PackSink> SprWriter<S> where ProtocolError: From<S::Error> {
    /// 🚀️ Writes the 32-byte header and seeds `chain_0 = blake3(header bytes)`.
    pub async fn begin(mut sink: S, options: &WriteOptions) -> Result<Self, ProtocolError> {
        let unknown = options.required_flags & !REQUIRED_KNOWN_MASK;
        if unknown != 0 {
            return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::UnknownRequiredFlags(unknown))));
        }
        let header = build_header_bytes(options.required_flags, options.optional_flags).await;
        sink.write_all(&header).await?;
        let chain_0 = *semio_framework_hash::hash(&header).as_bytes();
        let mut pending_chain_hasher = semio_framework_hash::Hasher::new();
        pending_chain_hasher.update(&chain_0);
        Ok(Self { sink, running_chain_hash: chain_0, pending_chain_hasher, pending_records_len: 0, pending_record_count: 0, next_commit_seq: 1, last_commit_offset: None })
    }

    /// ▶️ Resumes without rewriting a header or committed byte. The sink must be positioned at the
    /// end of the fully verified prefix, and the caller must hold exclusive storage authority over
    /// it; the consumed span is protocol metadata, not permission to append to arbitrary storage.
    pub async fn resume_verified(sink: S, span: retained::VerifiedSprSpan) -> Result<Self, ProtocolError> {
        let position = sink.position().await;
        if position != span.end() {
            return Err(malformed("verified append position", position, "sink must end at the verified committed prefix").await);
        }
        let next_commit_seq = span.sequence().checked_add(1).ok_or(ProtocolError::LimitExceeded("commit sequence exhausted"))?;
        let running_chain_hash = *span.chain();
        let mut pending_chain_hasher = semio_framework_hash::Hasher::new();
        pending_chain_hasher.update(&running_chain_hash);
        Ok(Self {
            sink,
            running_chain_hash,
            pending_chain_hasher,
            pending_records_len: 0,
            pending_record_count: 0,
            next_commit_seq,
            last_commit_offset: (span.sequence() != 0).then_some(span.commit_offset()),
        })
    }

    /// 📍️ Current absolute write position — the offset the next record/commit will start at.
    pub async fn position(&self) -> u64 {
        self.sink.position().await
    }

    /// 🔗️ The chain hash of the last commit — `chain_0 = blake3(header)` before the first, the
    /// verified span's chain after `resume_verified`. Records written since that commit do not move it,
    /// so a sink that has already handed its committed bytes to storage can still link a successor.
    pub fn committed_chain_hash(&self) -> [u8; 32] {
        self.running_chain_hash
    }

    pub async fn begin_identity_record(&mut self, kind: u8, critical: bool, payload_len: usize) -> Result<SprIdentityRecord<'_, S>, ProtocolError> {
        let start_offset = self.sink.position().await;
        let flags = frame_flags(false, critical, 0);
        let body_len = 2u64.checked_add(payload_len as u64).ok_or(ProtocolError::LimitExceeded("record body length overflow"))?;
        let mut body_len_bytes = [0u8; 10];
        let body_len_bytes = fixed_varint(body_len, &mut body_len_bytes);
        let frame_len = body_len_bytes.len().checked_add(body_len as usize).and_then(|len| len.checked_add(8)).ok_or(ProtocolError::LimitExceeded("record frame length overflow"))? as u64;
        let fixed = [kind, flags];
        let mut crc = crate::codec::Crc32cCursor::new();
        crc.update_page(&fixed);
        let mut digest = semio_framework_hash::Hasher::new();
        for fragment in [body_len_bytes, fixed.as_slice()] {
            digest.update(fragment);
            self.sink.write_all(fragment).await?;
        }
        Ok(SprIdentityRecord { owner: self, start_offset, payload_len, written: 0, frame_len, crc, digest })
    }

    /// 🖇️ Frames (compressing per `codec`), CRCs, and writes one record. Returns its start
    /// offset. Folds the frame's `blake3` digest into the pending commit-chain accumulator — the
    /// digest covers the WHOLE on-disk frame (length-prefix through `back_len`), matching the
    /// contract's `digest_i = blake3(full frame bytes of record i)`.
    pub async fn write_record(&mut self, kind: u8, critical: bool, payload: &[u8], codec: crate::codec::ids::CodecId) -> Result<u64, ProtocolError> {
        if codec.0 == 0 {
            let mut record = self.begin_identity_record(kind, critical, payload.len()).await?;
            record.write_fragment(payload).await?;
            return record.finish().await;
        }
        let start_offset = self.sink.position().await;
        let (compressed, raw_len, stored) = prepare_payload(codec, payload).await?;
        let flags = frame_flags(compressed, critical, codec.0);
        let (frame_len, digest) = write_frame_retained(&mut self.sink, kind, flags, raw_len, stored.as_ref()).await?;
        self.pending_chain_hasher.update(&digest);
        self.pending_records_len += frame_len;
        self.pending_record_count = self.pending_record_count.checked_add(1).ok_or(ProtocolError::LimitExceeded("record_count exceeds u32 per commit generation"))?;
        Ok(start_offset)
    }

    /// ⛓️ Writes a `REC_COMMIT` frame covering everything since the last commit (or the
    /// header, for the first).await: `chain_n = blake3(chain_{n-1} || digest_1 || .. || digest_k)`.
    /// Returns the commit frame's start offset.
    pub async fn commit(&mut self) -> Result<u64, ProtocolError> {
        let next_commit_seq = self.next_commit_seq.checked_add(1).ok_or(ProtocolError::LimitExceeded("commit sequence exhausted"))?;
        let offset = self.sink.position().await;
        let chain_hash = *self.pending_chain_hasher.finalize().as_bytes();

        let commit_seq = self.next_commit_seq;
        let prev_commit_offset = self.last_commit_offset.unwrap_or(0);
        let payload = write_commit_payload(commit_seq, prev_commit_offset, self.pending_records_len, self.pending_record_count, &chain_hash).await;
        let flags = frame_flags(false, true, 0);
        write_frame_retained(&mut self.sink, crate::REC_COMMIT, flags, None, &payload).await?;

        self.running_chain_hash = chain_hash;
        self.pending_chain_hasher = semio_framework_hash::Hasher::new();
        self.pending_chain_hasher.update(&chain_hash);
        self.pending_records_len = 0;
        self.pending_record_count = 0;
        self.next_commit_seq = next_commit_seq;
        self.last_commit_offset = Some(offset);
        Ok(offset)
    }

    /// 📤️ Unwraps the underlying sink (e.g. to hand a `Vec<u8>` or file handle onward).
    pub async fn into_sink(self) -> S {
        self.sink
    }
}
//#endregion 🔖️Writer

//#region 🔖️Recovery
/// 📋️ What a `recover` call found: how much of the file is trustworthy and where.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RecoveryReport {
    pub records_recovered: u64,
    /// 📏️ Design choice: the absolute count of trusted bytes from the start of the file —
    /// i.e. the offset callers should truncate/slice to (`&bytes[..bytes_recovered]`), not merely
    /// "bytes of record payload." Always `>= HEADER_SIZE` (the header itself always counts).
    pub bytes_recovered: u64,
    pub last_commit_seq: u64,
    pub last_commit_offset: u64,
    pub torn_tail_bytes: u64,
}

/// 🔀️ Which recovered boundary a caller trusts.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum RecoveryMode {
    #[default]
    LastCommit,
    LastValidRecord,
}

/// 🔍️ How much a reader verifies before trusting decoded content.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum VerificationLevel {
    Trusted,
    #[default]
    Standard,
    Full,
}

/// 🔢️ Reads one LEB128 varint at an absolute source offset, one byte at a time so it never
/// over-reads a legitimately short remaining source. Mirrors `os_pack::format::read_varint_u64_at`.
async fn read_varint_via_source<S: PackSource>(source: &S, offset: u64, total_len: u64) -> Result<(u64, u64), ProtocolError> where ProtocolError: From<S::Error> {
    let mut tmp: Vec<u8> = Vec::with_capacity(10);
    let mut i = 0u64;
    loop {
        if offset + i >= total_len {
            return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::Truncated(offset + i))));
        }
        let mut byte = [0u8; 1];
        source.read_exact_at(offset + i, &mut byte).await?;
        tmp.push(byte[0]);
        i += 1;
        if byte[0] & 0x80 == 0 {
            break;
        }
        if i >= 10 {
            return Err(malformed("varint", offset, "overlong varint (exceeds 10 bytes)").await);
        }
    }
    let mut pos = 0usize;
    let value = crate::codec::read_varint_u64(&tmp, &mut pos)?;
    Ok((value, i))
}

/// 👓️ `(kind, flags, raw_len, owned payload, frame_len)` — the owning twin of `RecordFrame`
/// for `PackSource`-backed reads, which cannot borrow zero-copy from a random-access source.
type SourceFrame = (u8, u8, Option<u64>, Vec<u8>, u64);

/// 👓️ Source-backed (owning, non-zero-copy) frame read at an absolute offset — the
/// `PackSource` twin of `decode_frame_in_slice`, used by `recover`'s forward scan and fast-path
/// commit walk, both of which operate over `PackSource` rather than an in-memory slice. Validates
/// `body_len` against `limits.max_frame_len` BEFORE allocating the body buffer.
async fn read_frame_via_source<S: PackSource>(source: &S, offset: u64, limits: &ProtocolLimits) -> Result<SourceFrame, ProtocolError> where ProtocolError: From<S::Error> {
    let total_len = source.len().await;
    let (body_len, body_len_width) = read_varint_via_source(source, offset, total_len).await?;
    if body_len < 2 {
        return Err(malformed("frame body_len", offset, "body_len smaller than kind+flags (2 bytes)").await);
    }
    if body_len > limits.max_frame_len {
        return Err(ProtocolError::LimitExceeded("frame body_len exceeds ProtocolLimits::max_frame_len"));
    }
    let body_start = offset + body_len_width;
    let body_end = body_start.checked_add(body_len).ok_or(ProtocolError::LimitExceeded("frame body offset overflow"))?;
    let trailer_end = body_end.checked_add(8).ok_or(ProtocolError::LimitExceeded("frame trailer offset overflow"))?;
    if trailer_end > total_len {
        return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::Truncated(body_start))));
    }
    let mut body = vec![0u8; body_len as usize];
    source.read_exact_at(body_start, &mut body).await?;
    let kind = body[0];
    let flags = body[1];
    let compressed = flags & FRAME_FLAG_COMPRESSED != 0;
    let mut payload_start = 2usize;
    let raw_len = if compressed {
        let mut p = payload_start;
        let v = crate::codec::read_varint_u64(&body, &mut p)?;
        payload_start = p;
        Some(v)
    } else {
        None
    };
    let mut trailer = [0u8; 8];
    source.read_exact_at(body_end, &mut trailer).await?;
    let stored_crc = u32::from_le_bytes(trailer[0..4].try_into().unwrap());
    let computed_crc = crate::codec::crc32c(&body);
    if stored_crc != computed_crc {
        return Err(ProtocolError::Pack(semio_framework_pack_error::PackError::Refusal(PackRefusal::ChecksumMismatch { segment: "frame", offset: body_end })));
    }
    let back_len = u32::from_le_bytes(trailer[4..8].try_into().unwrap()) as u64;
    let frame_len = trailer_end - offset;
    if back_len != frame_len {
        return Err(ProtocolError::FrameFraming(offset));
    }
    let payload = body.split_off(payload_start);
    Ok((kind, flags, raw_len, payload, frame_len))
}

/// ⚡️ Fast path: probes the last `COMMIT_FRAME_LEN` bytes for a valid `REC_COMMIT` frame
/// reaching exactly EOF, then walks `prev_commit_offset` all the way back to `commit_seq == 1`,
/// re-validating (CRC + critical bit + sequence linkage) every commit frame along the way — O(commit
/// count), never touching an intervening non-commit record. `None` on any failure, signalling the
/// caller to fall back to the forward scan; a fast-path success always means `torn_tail_bytes == 0`
/// (the tail commit frame ends exactly at EOF), so it is valid regardless of `RecoveryMode`.
async fn try_fast_path<S: PackSource>(source: &S, total_len: u64, limits: &ProtocolLimits) -> Option<RecoveryReport> where ProtocolError: From<S::Error> {
    if total_len < HEADER_SIZE as u64 + COMMIT_FRAME_LEN {
        return None;
    }
    let tail_offset = total_len - COMMIT_FRAME_LEN;
    let (kind, flags, _raw_len, payload, frame_len) = read_frame_via_source(source, tail_offset, limits).await.ok()?;
    if kind != crate::REC_COMMIT || frame_len != COMMIT_FRAME_LEN || flags & FRAME_FLAG_CRITICAL == 0 {
        return None;
    }
    let mut current = parse_commit_payload(&payload).ok()?;
    let last_commit_seq = current.commit_seq;
    let last_commit_offset = tail_offset;
    let mut num_commits = 1u64;
    let mut records_sum = current.record_count as u64;
    let mut cursor_offset = tail_offset;

    loop {
        if current.commit_seq == 1 {
            if current.prev_commit_offset != 0 {
                return None;
            }
            break;
        }
        let prev_offset = current.prev_commit_offset;
        if prev_offset == 0 || prev_offset >= cursor_offset {
            return None;
        }
        let (prev_kind, prev_flags, _prev_raw_len, prev_payload, _prev_frame_len) = read_frame_via_source(source, prev_offset, limits).await.ok()?;
        if prev_kind != crate::REC_COMMIT || prev_flags & FRAME_FLAG_CRITICAL == 0 {
            return None;
        }
        let prev_commit = parse_commit_payload(&prev_payload).ok()?;
        if prev_commit.commit_seq != current.commit_seq - 1 {
            return None;
        }
        num_commits += 1;
        records_sum += prev_commit.record_count as u64;
        cursor_offset = prev_offset;
        current = prev_commit;
    }

    Some(RecoveryReport { records_recovered: records_sum + num_commits, bytes_recovered: total_len, last_commit_seq, last_commit_offset, torn_tail_bytes: 0 })
}

/// 🚑️ Recovers a `.spr` source: validates the header, then tries the O(commits) fast path
/// before falling back to a bounded forward scan from `HEADER_SIZE`, stopping at the first invalid
/// or truncated frame. See the contract's four-step algorithm (reproduced in the inline comments).
pub async fn recover<S: PackSource>(source: &S, limits: &ProtocolLimits, mode: RecoveryMode) -> Result<RecoveryReport, ProtocolError> where ProtocolError: From<S::Error> {
    let total_len = source.len().await;
    if total_len > limits.max_file_len {
        return Err(ProtocolError::LimitExceeded("file exceeds ProtocolLimits::max_file_len"));
    }
    // (1) validate header
    validate_header(source).await?;

    if total_len == HEADER_SIZE as u64 {
        return Ok(RecoveryReport { records_recovered: 0, bytes_recovered: HEADER_SIZE as u64, last_commit_seq: 0, last_commit_offset: 0, torn_tail_bytes: 0 });
    }

    // (2) fast path
    if let Some(report) = try_fast_path(source, total_len, limits).await {
        return Ok(report);
    }

    // (3) forward scan from offset 32, tracking last_valid_end and last_commit_end
    let mut pos = HEADER_SIZE as u64;
    let mut last_valid_end = HEADER_SIZE as u64;
    let mut last_commit_end = HEADER_SIZE as u64;
    let mut last_commit_seq = 0u64;
    let mut last_commit_offset = 0u64;
    let mut records_valid = 0u64;
    let mut records_at_commit = 0u64;

    while pos < total_len {
        let frame_start = pos;
        match read_frame_via_source(source, pos, limits).await {
            Ok((kind, _flags, _raw_len, payload, frame_len)) => {
                records_valid += 1;
                if records_valid > limits.max_record_count {
                    return Err(ProtocolError::LimitExceeded("record count exceeds ProtocolLimits::max_record_count"));
                }
                pos += frame_len;
                last_valid_end = pos;
                if kind == crate::REC_COMMIT {
                    if let Ok(commit) = parse_commit_payload(&payload) {
                        last_commit_seq = commit.commit_seq;
                        last_commit_offset = frame_start;
                        last_commit_end = pos;
                        records_at_commit = records_valid;
                    }
                }
            }
            Err(_) => break,
        }
    }

    // (4) LastCommit trusts only [0, last_commit_end); LastValidRecord trusts through last_valid_end
    let (trusted_end, records_recovered) = match mode {
        RecoveryMode::LastCommit => (last_commit_end, records_at_commit),
        RecoveryMode::LastValidRecord => (last_valid_end, records_valid),
    };
    Ok(RecoveryReport { records_recovered, bytes_recovered: trusted_end, last_commit_seq, last_commit_offset, torn_tail_bytes: total_len - trusted_end })
}
//#endregion 🔖️Recovery

//#region 🔖️Crypto
/// 🔗️ The commit chain's hash primitive: `blake3`, owned here so `protocol_core` stays
/// dependency-free (per the family's crypto-trait-only rule).
pub struct Blake3Hasher;

impl RecordHasher for Blake3Hasher {
    fn hash(&self, bytes: &[u8]) -> [u8; 32] {
        *semio_framework_hash::hash(bytes).as_bytes()
    }
}
//#endregion 🔖️Crypto

//#region 🧪️Tests
#[cfg(test)]
#[path = "🧪️tests/🔬️unit/🦀️.rs"]
mod tests;
//#endregion 🧪️Tests

