        super::close_retained_binding(&mut state.source, grant)
    }

    fn terminal_is_empty(&self) -> bool {
        self.closing && self.bytes.terminal_is_empty() && self.output.is_none() && self.close.is_empty() && self.source.is_none()
    }
}

